def sequence_a(n):
    a = {}
    a[1] = 1
    a[2] = 1
    for i in range(3, n + 1):
        # a_i = a_{a_{i-1}} + a_{i - a_{i-1}}
        if i - 1 in a and a[i-1] in a and i - a[i-1] in a:
            next_a = a[a[i-1]] + a[i - a[i-1]]
            a[i] = next_a
        else:
            # Should not happen if we calculate in order
            a[i] = None
    return a

N_limit = 32
A_values = sequence_a(N_limit)

print("--- Sequence A values ---")
for i in range(1, N_limit + 1):
    print(f"a_{i} = {A_values[i]}")

print("\n--- Powers of 2 ---")
for k in range(1, 6): # Check up to 2^5 = 32
    p = 2**k
    print(f"a_{p} = {A_values[p]}")

def calculate_a(n, memo):
    if n in memo:
        return memo[n]

    if n == 1 or n == 2:
        return 1

    # a_n = a_{a_{n-1}} + a_{n - a_{n-1}}
    try:
        a_n_minus_1 = calculate_a(n - 1, memo)

        term1_index = a_n_minus_1
        term2_index = n - a_n_minus_1

        term1 = calculate_a(term1_index, memo)
        term2 = calculate_a(term2_index, memo)

        result = term1 + term2
        memo[n] = result
        return result
    except RecursionError:
        return "Recursion Limit Reached"

# Calculate up to n=10
N_max = 10
memo = {}
results = {}

for n in range(1, N_max + 1):
    results[n] = calculate_a(n, memo)

print("n:", list(results.keys()))
print("a_n:", list(results.values()))

def calculate_a(N):
    a = [0] * (N + 1)
    if N >= 1:
        a[1] = 1
    if N >= 2:
        a[2] = 1

    for n in range(3, N + 1):
        k = a[n-1]
        # Since we established a[n-1] < n, k <= n-1, so n-k >= 1.
        a[n] = a[k] + a[n - k]
    return a

N_max = 30
sequence = calculate_a(N_max)

print("n | a_n")
for n in range(1, N_max + 1):
    print(f"{n} | {sequence[n]}")

